package com.interviewassistant.licensing.security;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.HexFormat;
import java.util.List;
import java.util.Optional;
import java.util.Set;

/**
 * Authenticates administrators by a high-entropy bearer token.
 *
 * <p>Design (and its limits, see docs/ADMIN_AUTH.md):
 * <ul>
 *   <li>A token is {@code ia_adm_} + 43 base64url characters = 256 random bits. It is generated by {@code AdminTokenTool}, shown
 *       once, and only its SHA-256 is placed in configuration. Hashing a 256-bit random token with plain SHA-256 is sound (there
 *       is nothing to brute-force); a slow password hash would add nothing.</li>
 *   <li>Every configured credential is compared on every attempt with {@link MessageDigest#isEqual} (constant time), without
 *       stopping at the first match, so response time does not reveal which credential matched.</li>
 *   <li>There are no user accounts, sessions, password reset or MFA. This is intentionally narrow: a small set of
 *       service-style credentials, each with scopes. Rotating one means editing configuration and restarting.</li>
 * </ul>
 */
public final class AdminAuthenticator {

    public static final String TOKEN_PREFIX = "ia_adm_";
    private static final int MAX_HEADER = 256;

    /** A configured credential: id, SHA-256 of its token, and what it may do. */
    public record Credential(String id, byte[] tokenSha256, Set<AdminScope> scopes) {
        public Credential {
            if (id == null || !id.matches("[A-Za-z0-9._-]{1,40}")) {
                throw new IllegalArgumentException("admin credential id must match [A-Za-z0-9._-]{1,40}");
            }
            if (tokenSha256 == null || tokenSha256.length != 32) {
                throw new IllegalArgumentException("admin credential " + id + " needs a 64-hex-character SHA-256 token hash");
            }
            if (scopes == null || scopes.isEmpty()) {
                throw new IllegalArgumentException("admin credential " + id + " needs at least one scope");
            }
            tokenSha256 = tokenSha256.clone();
            scopes = Set.copyOf(scopes);
        }

        public static Credential ofHex(String id, String sha256Hex, Set<AdminScope> scopes) {
            try {
                return new Credential(id, HexFormat.of().parseHex(sha256Hex == null ? "" : sha256Hex.trim()), scopes);
            } catch (IllegalArgumentException e) {
                throw new IllegalArgumentException("admin credential " + id + " needs a 64-hex-character SHA-256 token hash");
            }
        }
    }

    private final List<Credential> credentials;

    public AdminAuthenticator(List<Credential> credentials) {
        this.credentials = List.copyOf(credentials);
    }

    public boolean hasCredentials() {
        return !credentials.isEmpty();
    }

    /** Resolves an {@code Authorization: Bearer <token>} header value, or empty if it does not identify a credential. */
    public Optional<AdminPrincipal> authenticate(String authorizationHeader) {
        if (authorizationHeader == null || authorizationHeader.length() > MAX_HEADER
                || !authorizationHeader.regionMatches(true, 0, "Bearer ", 0, 7)) {
            return Optional.empty();
        }
        String token = authorizationHeader.substring(7).trim();
        if (!token.startsWith(TOKEN_PREFIX)) {
            return Optional.empty();
        }
        byte[] presented = sha256(token);
        Credential match = null;
        for (Credential c : credentials) {
            if (MessageDigest.isEqual(presented, c.tokenSha256()) && match == null) {
                match = c;
            }
        }
        return match == null ? Optional.empty() : Optional.of(new AdminPrincipal(match.id(), match.scopes()));
    }

    // ------------------------------------------------------------------ token generation (used by AdminTokenTool)

    public static String generateToken(SecureRandom random) {
        byte[] bytes = new byte[32];
        random.nextBytes(bytes);
        return TOKEN_PREFIX + Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    public static String hashHex(String token) {
        return HexFormat.of().formatHex(sha256(token));
    }

    private static byte[] sha256(String s) {
        try {
            return MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}
